import json


class ImportProblem(Exception):
    def __init__(self, line):
        self.line = line
        super().__init__(f'invalid line {line}')


def _valid_count(value):
    # bool is a subclass of int, but the spec says bool counts are invalid.
    if isinstance(value, bool):
        return False
    return isinstance(value, int)


def _parse_line(raw, line):
    try:
        record = json.loads(raw.decode('utf-8'))
    except (UnicodeDecodeError, ValueError):
        raise ImportProblem(line)
    if not isinstance(record, dict):
        raise ImportProblem(line)
    record_id = record.get('id')
    if not isinstance(record_id, str) or record_id == '':
        raise ImportProblem(line)
    if not _valid_count(record.get('count')):
        raise ImportProblem(line)
    return record


def import_bytes(payload, store):
    # Validate every line first; only commit once the whole payload is valid,
    # so a rejected import leaves the store exactly unchanged.
    records = []
    for line, raw in enumerate(payload.splitlines(), 1):
        if not raw.strip():
            continue
        records.append(_parse_line(raw, line))
    for record in records:
        store.append(record)
    return len(records)

